(function(){
'use strict';
const R=Rift;let state=R.load(localStorage),page=document.body.dataset.page,selected=state?.location||'camp',timer,mapView,sceneSelection=null,sceneFeedback='';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ART={"story-01":{"title":"Rushing to Work","sheet":"story-sheet.jpg","box":[2,0,338,188]},"story-02":{"title":"Earth Tearing Apart","sheet":"story-sheet.jpg","box":[347,0,338,188]},"story-03":{"title":"Freefall","sheet":"story-sheet.jpg","box":[693,0,336,188]},"story-04":{"title":"Impact","sheet":"story-sheet.jpg","box":[1036,0,338,188]},"story-05":{"title":"Struggling Free","sheet":"story-sheet.jpg","box":[2,194,338,185]},"story-06":{"title":"Hellscape View","sheet":"story-sheet.jpg","box":[347,194,338,185]},"story-07":{"title":"Hearing Maya","sheet":"story-sheet.jpg","box":[693,194,336,185]},"story-08":{"title":"Clearing the Rubble","sheet":"story-sheet.jpg","box":[1036,194,338,185]},"story-09":{"title":"Rescued and Together","sheet":"story-sheet.jpg","box":[2,386,338,122]},"story-10":{"title":"The Electric Glow","sheet":"story-sheet.jpg","box":[347,386,338,122]},"story-11":{"title":"Clean Zone","sheet":"story-sheet.jpg","box":[693,386,336,122]},"story-12":{"title":"Scavenging Supplies","sheet":"story-sheet.jpg","box":[1036,386,338,122]},"story-13":{"title":"Ground Tremors Again","sheet":"story-sheet.jpg","box":[2,515,338,123]},"story-14":{"title":"The Light Expands","sheet":"story-sheet.jpg","box":[347,515,338,123]},"story-15":{"title":"Seeing the Past","sheet":"story-sheet.jpg","box":[693,515,336,123]},"story-16":{"title":"The Final Run","sheet":"story-sheet.jpg","box":[1036,515,338,123]},"story-17":{"title":"The Flash","sheet":"story-sheet.jpg","box":[2,645,338,123]},"story-18":{"title":"Arrival","sheet":"story-sheet.jpg","box":[347,645,338,123]},"story-19":{"title":"Exploring the Wild","sheet":"story-sheet.jpg","box":[693,645,336,123]},"story-20":{"title":"Establishing Camp","sheet":"story-sheet.jpg","box":[1036,645,338,123]},"frontier-01":{"title":"The New Frontier","sheet":"frontier-sheet.jpg","box":[2,0,338,188]},"frontier-02":{"title":"Dire Wolf Stalk","sheet":"frontier-sheet.jpg","box":[347,0,338,188]},"frontier-03":{"title":"Scavenged Tools","sheet":"frontier-sheet.jpg","box":[693,0,336,188]},"frontier-04":{"title":"Cave Bear Cave","sheet":"frontier-sheet.jpg","box":[1036,0,338,188]},"frontier-05":{"title":"Collecting Firewood","sheet":"frontier-sheet.jpg","box":[2,194,338,185]},"frontier-06":{"title":"River Fishing Area","sheet":"frontier-sheet.jpg","box":[347,194,338,185]},"frontier-07":{"title":"Strange Sound","sheet":"frontier-sheet.jpg","box":[693,194,336,185]},"frontier-08":{"title":"Building the Shelter","sheet":"frontier-sheet.jpg","box":[1036,194,338,185]},"frontier-09":{"title":"Woolly Rhino Sighting","sheet":"frontier-sheet.jpg","box":[2,386,338,122]},"frontier-10":{"title":"Megaloceros Antlers","sheet":"frontier-sheet.jpg","box":[347,386,338,122]},"frontier-11":{"title":"Saber-tooth Ambush","sheet":"frontier-sheet.jpg","box":[693,386,336,122]},"frontier-12":{"title":"Distant Thunder Bird","sheet":"frontier-sheet.jpg","box":[1036,386,338,122]},"frontier-13":{"title":"Finding a Scavenged Car Battery","sheet":"frontier-sheet.jpg","box":[2,515,338,123]},"frontier-14":{"title":"Anomaly Road Sign","sheet":"frontier-sheet.jpg","box":[347,515,338,123]},"frontier-15":{"title":"Hunting the Chase","sheet":"frontier-sheet.jpg","box":[693,515,336,123]},"frontier-16":{"title":"Scavenged Items Cache","sheet":"frontier-sheet.jpg","box":[1036,515,338,123]},"frontier-17":{"title":"River Predators","sheet":"frontier-sheet.jpg","box":[2,645,338,123]},"frontier-18":{"title":"Gathering Berries","sheet":"frontier-sheet.jpg","box":[347,645,338,123]},"frontier-19":{"title":"Camp Fortification","sheet":"frontier-sheet.jpg","box":[693,645,336,123]},"frontier-20":{"title":"Home Campfire","sheet":"frontier-sheet.jpg","box":[1036,645,338,123]}};
Object.assign(ART,{"scene-wreck":{"title":"Mustang wreck at Broken Ridge","sheet":"exploration-scenes.png","box":[0,0,768,512],"width":1536,"height":1024},"scene-forest":{"title":"Forest floor with searchable plants and fallen wood","sheet":"exploration-scenes.png","box":[768,0,768,512],"width":1536,"height":1024},"scene-camp":{"title":"River camp with shelter, fire ring, basket, and fishing gear","sheet":"exploration-scenes.png","box":[0,512,768,512],"width":1536,"height":1024},"scene-rift":{"title":"Rift clearing with monolith and modern debris","sheet":"exploration-scenes.png","box":[768,512,768,512],"width":1536,"height":1024}});
let artSerial=0;
function panel(id,cls=''){let clip='panel-clip-'+(++artSerial);let a=ART[id];if(!a)return '';return `<figure class="art-panel ${cls}"><svg width="${a.box[2]}" height="${a.box[3]}" viewBox="${a.box.join(' ')}" role="img" aria-label="${a.title}" xmlns="http://www.w3.org/2000/svg"><title>${a.title}</title><defs><clipPath id="${clip}"><rect x="${a.box[0]}" y="${a.box[1]}" width="${a.box[2]}" height="${a.box[3]}"/></clipPath></defs><image clip-path="url(#${clip})" href="assets/art/${a.sheet}" width="${a.width||1376}" height="${a.height||768}"/></svg></figure>`;}
function storyPanels(i){return '<div class="story-panels">'+Array.from({length:5},(_,n)=>panel('story-'+String(i*5+n+1).padStart(2,'0'))).join('')+'</div>';}
function locationPanel(){return panel(R.places.find(p=>p.id===state.location)?.art||'frontier-01');}
function recipePanel(id){let map={shelter:'frontier-08',fishing:'frontier-06',fire:'frontier-20',smelter:'frontier-03',spear:'frontier-03',axe:'frontier-05',walls:'frontier-19',trap:'frontier-02',rope:'frontier-01',food:'frontier-06',coat:'frontier-02',med:'frontier-18',permanent:'frontier-19',transmitter:'frontier-13'};return panel(map[id]);}

function bondMeters(){let b=R.Bond.ensure(state);return `<div class="bond-meters">${[['trust','Trust'],['affection','Affection']].map(([k,label])=>`<div><div class="row spread"><span>${label}</span><strong>${b[k]} <small>/ 100</small></strong></div><div class="bond-track" role="progressbar" aria-label="${label}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${b[k]}"><i style="width:${b[k]}%"></i></div></div>`).join('')}</div>`;}
function bondInline(){let b=R.Bond.ensure(state),p=R.Bond.stage(state);return `<div class="bond-inline"><span class="gold">${p.status}</span><span>Trust ${b.trust} · Affection ${b.affection}</span>${b.synergy?`<small>${b.committed?'Shared Future support':'Synergy active with Maya'}</small>`:''}</div>`;}
function bondCard(){let b=R.Bond.ensure(state),phase=R.Bond.stage(state),event=R.Bond.next(state),safe=state.location==='camp'&&!state.encounter&&!state.dead;return `<section class="card bond-card" aria-label="Relationship with Maya"><div class="row spread"><div class="eyebrow">Maya & ${esc(state.name)} · Act ${phase.act}</div><span class="pill">${phase.status}</span></div><h2>${phase.title}</h2><p>Trust grows through reliability. Affection grows through the time you choose to share.</p>${bondMeters()}<p class="bond-next">${event?'A quiet moment is ready: '+R.Bond.titles[event]+'.':R.Bond.requirements(state)}</p>${event?`<button class="primary" data-bond-event="${event}">Share this moment</button>`:''}<div class="bond-activities"><button data-bond-activity="talk" ${!safe||b.daily.talk===state.day?'disabled':''}>Listen & talk <small>1h · +3 Trust / +4 Affection</small></button><button data-bond-activity="meal" ${!safe||b.daily.meal===state.day||!R.can(state,{food:1})?'disabled':''}>Share a meal <small>1h · 1 ration · +3 / +5</small></button><button data-bond-activity="gift" ${!safe||b.daily.gift===state.day||!R.can(state,{rope:1,wire:1})?'disabled':''}>Weave a keepsake <small>1h · 1 rope + 1 wire · +2 / +6</small></button></div><p class="tiny muted">Each camp activity is available once per game day. Gathering together also builds your bond once per day.${!safe?' Return to a safe river camp to spend time together.':''}</p><div class="bond-perks"><h3>Companion support</h3><p>${b.synergy?'✓ Synergy: every fourth successful gathering action with Maya saves 1 hour.':'◇ Synergy unlocks after The Reminiscent Echo.'}</p><p>${b.committed?'✓ Shared Future: Maya reduces combat damage by 6 while accompanying you, adds +2 to herb/berry/sapling yields, and produces +2 supplies on daily fishing, foraging, and cooking assignments.':'◇ Shared Future support unlocks when you choose commitment.'}</p></div>${b.committed?`<div class="bond-ending"><span class="eyebrow">Ending path unlocked</span><h3>Shared Future</h3><p>${state.flags.signal?'The transmitter is live. Your shared future is ready to remember.':'Complete Bridging the Eras to see your shared ending.'}</p><button id="shared-ending" ${!state.flags.signal?'disabled':''}>View Shared Future ending</button></div>`:''}<a class="tiny gold" href="journal.html">Relationship memories in your journal ↗</a></section>`;}
function bondJournal(){let b=R.Bond.ensure(state),phase=R.Bond.stage(state);return `<section class="card bond-card"><div class="eyebrow">Maya Lin · Relationship journal</div><h2>${phase.title}</h2>${bondMeters()}<p>${R.Bond.requirements(state)}</p><div class="bond-memory-list">${['blanket','echo','confession'].map((id,i)=>`<div class="bond-memory"><span class="number">0${i+1}</span><div><h3>${R.Bond.titles[id]}</h3><p class="tiny">${b.seen[id]?'Remembered · Day '+b.history.find(h=>h.id===id)?.day:['Survive the first cold night after building the lean-to.','Trust 31+ and a shared Fresh Catch / Apex Predator success.','Trust 71+, Affection 80+, late game, and an evening at camp.'][i]}</p>${b.seen[id]?`<button data-bond-replay="${id}">Read memory</button>`:''}</div></div>`).join('')}</div>${b.committed?'<p class="gold">Shared Future ending path unlocked.</p>':b.friendship?'<p class="gold">Lifelong Allies · You chose an enduring friendship.</p>':''}<a class="button" href="camp.html">Spend time at camp</a></section>`;}
let bondDeferred=new Set();
function bondScene(id,replay=false){let sc=R.Bond.scene(state,id),b=R.Bond.ensure(state),memory=b.history.find(h=>h.id===id);let html=`<div class="bond-cinematic">${panel('frontier-20')}<span>A quiet moment by the river</span></div><p>${esc(sc.lead)}</p><div class="bond-dialogue">${sc.lines.map(([speaker,line])=>`<p><strong>${esc(speaker)}</strong><span>“${esc(line)}”</span></p>`).join('')}</div>`;if(replay){let chosen=sc.choices.find(c=>c[0]===memory?.choice);modal(sc.title+' · Memory',html+`<p class="tiny gold">Your choice: ${esc(chosen?.[1]||'A moment shared.')}</p>`,[['Close memory',()=>{}]]);return;}if(R.Bond.next(state)!==id){notify('Return to camp when this moment is ready.');return;}let actions=sc.choices.map(([choice,label])=>[label,()=>{action(()=>R.Bond.resolve(state,id,choice));if(id==='confession'&&state.relationship.seen.confession){let committed=state.relationship.committed;modal(committed?'A home in each other':'A lasting friendship',`<div class="bond-cinematic commitment">${panel('frontier-20')}<span>${committed?'Shared Future · Ending path unlocked':'Lifelong Allies'}</span></div><p>${committed?'You hold Maya close as the view drifts back over the campfire, the rushing river, and the vast, beautiful valley. Whatever era surrounds you, you have found home in each other.':'You thank Maya for her honesty. Together, you choose a friendship built on care and mutual respect. The valley remains a home you will protect side by side.'}</p>`,[['Continue your story',()=>{}]])}}]);actions.push(['Another time',()=>bondDeferred.add(id)]);modal(sc.title,html,actions);RiftAudio.speak(sc.lines.map(([speaker,line])=>speaker+' says, '+line).join(' '));}
function bindBond(){document.querySelectorAll('[data-bond-activity]').forEach(b=>b.onclick=()=>action(()=>R.Bond.activity(state,b.dataset.bondActivity)));document.querySelectorAll('[data-bond-event]').forEach(b=>b.onclick=()=>bondScene(b.dataset.bondEvent));document.querySelectorAll('[data-bond-replay]').forEach(b=>b.onclick=()=>bondScene(b.dataset.bondReplay,true));if($('#shared-ending'))$('#shared-ending').onclick=()=>{let ending=R.Bond.ending(state);if(ending)modal(ending.title,`<div class="bond-cinematic commitment">${panel('frontier-20')}<span>A home across the ages</span></div><p class="ending-copy">${esc(ending.text)}</p><p class="tiny gold">Your adventure continues in free play.</p>`,[['Return to camp',()=>{}]])};}

function cheatMutation(fn){let message=fn();save();render();showCheats();notify(message);}
function showCheats(){if(!RiftCheats.unlocked()){modal('Unlock cheats','<p>Enter the access code to open the Cheats menu. Codes are case-sensitive.</p><form id="cheats-unlock-form"><label class="tiny" for="cheat-code">Access code</label><input id="cheat-code" type="password" autocomplete="off" spellcheck="false" required><p id="cheat-code-error" class="health tiny" role="status"></p><button class="primary" type="submit">Unlock menu</button></form>',[['Cancel',()=>render()]]);$('#cheats-unlock-form').onsubmit=e=>{e.preventDefault();if(RiftCheats.unlock($('#cheat-code').value)){showCheats();}else{$('#cheat-code-error').textContent='Incorrect code. Try again.';$('#cheat-code').value='';$('#cheat-code').focus();}};return;}
if(!state?.started){modal('Cheats unlocked','<p>Begin or continue a journey to use cheats. All options start off.</p>',[['Close',()=>{}],['Lock menu',()=>{RiftCheats.lock();notify('Cheats menu locked.')}]]);return;}
let c=RiftCheats.state(state);modal('Cheats',`<div class="cheat-status ${c.everUsed?'used':''}">${c.everUsed?'CHEATS USED · This save has used cheats.':'All cheats are optional. Your save has not used any.'}</div><p class="tiny">Toggle ongoing effects or apply an instant action. Supply and relationship changes stay in the save after you disable cheats.</p><div class="cheat-options">${RiftCheats.options.map(o=>`<label class="cheat-option"><div><strong>${o.name}</strong><span>${o.desc}</span></div><input type="checkbox" data-cheat="${o.id}" ${c[o.id]?'checked':''}></label>`).join('')}</div><div class="cheat-instant"><button data-cheat-action="meters">Restore survival meters <small>Instantly restore health, hunger, hydration, and warmth.</small></button><button data-cheat-action="supplies">Spawn supply cache <small>Add 50 of every resource, food, water, and trap.</small></button><button data-cheat-action="relationship">Max relationship stats <small>Trust 100 / Affection 100. Scenes and commitment still require your choices.</small></button></div>`,[['Return to game',()=>render()],['Disable ongoing cheats',()=>cheatMutation(()=>RiftCheats.disable(state))],['Lock menu',()=>{RiftCheats.lock();render();notify('Cheats menu locked.')}]]);
document.querySelectorAll('[data-cheat]').forEach(el=>el.onchange=()=>cheatMutation(()=>RiftCheats.set(state,el.dataset.cheat,el.checked)));document.querySelectorAll('[data-cheat-action]').forEach(el=>el.onclick=()=>cheatMutation(()=>RiftCheats.apply(state,el.dataset.cheatAction)));}

function sceneNodeName(o){return RiftScenes.visible(state,o)?o.name:'Unidentified discovery';}
function renderExploration(){let S=RiftScenes,scene=S.data(state);if(!scene)return '<div class="card"><p>No scene is available here.</p><a href="world.html">Return to the map</a></div>';if(!scene.objects.some(o=>o.id===sceneSelection))sceneSelection=scene.objects.find(o=>!S.found(state,state.location,o.id))?.id||scene.objects[0].id;let o=scene.objects.find(o=>o.id===sceneSelection),done=S.found(state,state.location,o.id),blocked=S.reason(state,o),known=S.visible(state,o),count=scene.objects.filter(o=>S.found(state,state.location,o.id)).length;
return top(scene.title,'Explore the scene. Examine objects, then choose what to search, collect, or read.')+`<div class="scene-hud" aria-label="Survival status"><span>Health <b>${state.health}</b></span><span>Food <b>${state.hunger}</b></span><span>Water <b>${state.thirst}</b></span><span>Warmth <b>${state.warmth}</b></span><span>${count}/${scene.objects.length} discovered</span></div><p class="scene-intro">${scene.intro}</p><div class="scene-layout"><section><div class="exploration-stage ${state.hour>=19||state.hour<6?'night':''} ${state.flashlight?'lit':''}">${panel(scene.art)}<div class="scene-hotspots">${scene.objects.map((n,i)=>`<button class="scene-hotspot ${S.found(state,state.location,n.id)?'found':''} ${sceneSelection===n.id?'selected':''} ${!S.visible(state,n)?'unidentified':''}" style="left:${n.x}%;top:${n.y}%" data-scene-select="${n.id}" aria-label="Examine ${sceneNodeName(n)}"><span>${S.found(state,state.location,n.id)?'✓':S.visible(state,n)?String(i+1).padStart(2,'0'):'?'}</span><small>${sceneNodeName(n)}</small></button>`).join('')}</div></div><div class="row scene-tools"><button id="light">Flashlight ${state.flashlight?'on':'off'} · ${state.battery}%</button><button data-act="battery" ${!R.can(state,{battery:1})?'disabled':''}>Replace battery · 1 battery</button><button id="scene-maya" ${!state.companion?'disabled':''}>Ask Maya for a clue</button></div><p id="scene-hint" class="tiny muted">${state.companion?'Maya is with you. She can identify hidden plants and help with heavy salvage.':'Bring Maya for plant identification, clues, and help salvaging the wreck.'}</p><div class="scene-object-list" role="group" aria-label="Objects in this scene">${scene.objects.map(n=>`<button data-scene-select="${n.id}" class="${sceneSelection===n.id?'selected':''}">${S.found(state,state.location,n.id)?'✓ ':'◇ '}${sceneNodeName(n)}</button>`).join('')}</div></section><aside class="card scene-detail" id="scene-detail" tabindex="-1"><div class="eyebrow">${done?'Discovery recorded':'Look closer'}</div><h2>${sceneNodeName(o)}</h2><p>${known?esc(o.text):'Something is easy to overlook here. Maya’s eye or a beam of light may reveal it.'}</p>${o.requires&&!S.found(state,state.location,o.requires)?'<p class="scene-requirement">First, pry open the crushed hood.</p>':''}${Object.keys(o.loot).length&&known?`<p class="tiny">Possible find: ${Object.entries(o.loot).map(([k,n])=>n+' '+R.names[k]).join(' · ')}</p>`:''}<button class="primary" id="scene-search" ${done||blocked?'disabled':''}>${done?'Already discovered':o.verb+' · '+S.cost(state,o)+'h'}</button>${blocked&&!done?`<p class="tiny health">${blocked}</p>`:''}${sceneFeedback?`<p class="scene-feedback" role="status">${esc(sceneFeedback)}</p>`:''}<p class="tiny muted">Looking around is free. Searching supplies usually takes an hour. Each discovery is saved once.</p><div class="scene-exits"><button id="special">Quest / investigate</button><a class="button" href="world.html">Return to map</a><a class="tiny gold" href="journal.html">Read discovery journal ↗</a></div></aside></div>`;}
function bindExploration(){document.querySelectorAll('[data-scene-select]').forEach(b=>b.onclick=()=>{sceneSelection=b.dataset.sceneSelect;sceneFeedback='';render();RiftAudio.effect('select');if(window.innerWidth<740)$('#scene-detail').scrollIntoView({block:'start',behavior:'auto'});});if($('#scene-search'))$('#scene-search').onclick=()=>{let before=RiftScenes.records(state).length;action(()=>{sceneFeedback=RiftScenes.search(state,sceneSelection);return sceneFeedback});if(RiftScenes.records(state).length>before){RiftAudio.effect('discovery');let o=RiftScenes.data(state).objects.find(o=>o.id===sceneSelection);RiftAudio.speak(o.text);}};if($('#scene-maya'))$('#scene-maya').onclick=()=>{let scene=RiftScenes.data(state),target=scene.objects.find(o=>!RiftScenes.found(state,state.location,o.id)&&o.hint)||scene.objects.find(o=>!RiftScenes.found(state,state.location,o.id));let hint=target?(target.hint||'Try looking more closely at '+target.name.toLowerCase()+'.'):'We’ve found everything here. Let’s compare our notes at camp.';$('#scene-hint').textContent='Maya: “'+hint+'”';RiftAudio.speak('Maya says, '+hint);if(target)document.querySelector('[data-scene-select="'+target.id+'"]')?.classList.add('maya-clue');};}
function discoveryJournal(){let records=RiftScenes.records(state);return `<section class="discovery-journal"><div class="eyebrow">Objects & discoveries</div><h2>The things we found</h2><p class="tiny">${records.length} discoveries saved. Search a location’s scene to uncover objects and clues.</p>${records.length?`<details><summary>Read discovered clues & field notes</summary>${[...records].reverse().map(d=>{let m=RiftScenes.memory(d.id);return `<article><span class="eyebrow">Day ${d.day} · ${m.scene.title}</span><h3>${m.object.name}</h3><p>${m.object.text}</p></article>`}).join('')}</details>`:''}<a class="button" href="scene.html">Explore your current location</a></section>`;}

function showAudio(){let a=RiftAudio.get();modal('Audio settings',`<p class="tiny">Original synthesized music and ambience, with optional device-voice narration. Audio starts after you enable it; your preferences are saved on this browser.</p><div class="audio-switches"><label><input id="audio-enabled" type="checkbox" ${a.enabled?'checked':''}> Enable audio</label><label><input id="audio-muted" type="checkbox" ${a.muted?'checked':''}> Mute all</label></div><div class="audio-sliders">${[['master','Master volume'],['music','Music'],['ambience','Ambience'],['effects','Sound effects'],['voice','Voice']].map(([key,label])=>`<label for="audio-${key}"><span>${label}<output id="audio-value-${key}">${a[key]}%</output></span><input type="range" id="audio-${key}" data-audio-volume="${key}" min="0" max="100" step="1" value="${a[key]}"></label>`).join('')}</div><label class="audio-narration"><input id="audio-narration" type="checkbox" ${a.narration?'checked':''}> Read discoveries and Maya’s clues aloud (device voice)</label><p class="tiny muted">Voice availability and sound output depend on your browser and device. Reading still works with all audio muted.</p><div class="row"><button id="audio-test-effects">Test effects</button><button id="audio-test-voice">Test voice</button></div><p id="audio-feedback" class="tiny" role="status"></p>`,[['Return to game',()=>{}]]);$('#audio-enabled').onchange=async e=>{RiftAudio.set('enabled',e.target.checked);if(e.target.checked){let ok=await RiftAudio.enable();$('#audio-feedback').textContent=ok?'Audio enabled. Use the sliders to mix each layer.':'Audio could not start in this browser. Try another tap or check device audio settings.';}else $('#audio-feedback').textContent='Audio disabled.';};$('#audio-muted').onchange=e=>{RiftAudio.set('muted',e.target.checked);$('#audio-feedback').textContent=e.target.checked?'All audio muted.':'Mute all off. Your volume mix is preserved.';};$('#audio-narration').onchange=e=>RiftAudio.set('narration',e.target.checked);document.querySelectorAll('[data-audio-volume]').forEach(el=>el.oninput=()=>{let key=el.dataset.audioVolume;RiftAudio.set(key,Number(el.value));$('#audio-value-'+key).textContent=el.value+'%';});$('#audio-test-effects').onclick=()=>{RiftAudio.effect('discovery');$('#audio-feedback').textContent=RiftAudio.get().enabled&&!RiftAudio.get().muted?'Playing the discovery effect at your current mix.':'Enable audio and switch off Mute all to hear the preview.';};$('#audio-test-voice').onclick=()=>{$('#audio-feedback').textContent=RiftAudio.speak('The river is clear. A new world awaits.',true)?'Voice preview requested at your current volume.':'Voice is muted, disabled, or unavailable. Enable audio and check Master and Voice volumes.';};}

function saveManualGame(){let result=RiftSaves.write(localStorage,state);if(result.ok){save();render();}notify(result.message);}
function loadManualGame(){let item=RiftSaves.read(localStorage);if(!item){notify('No compatible manual save was found on this browser.');return;}modal('Load saved game?',`<p>Load ${esc(item.state.name)}’s saved journey from Day ${item.state.day}, ${String(item.state.hour).padStart(2,'0')}:00?</p><p class="tiny">This replaces the current autosave with your manual checkpoint.</p>`,[['Load saved game',()=>{state=RiftSaves.restore(localStorage);if(!state){notify('The checkpoint could not be loaded.');return;}selected=state.location;sceneSelection=null;sceneFeedback='';save();go(state.prologue<4?'story.html':'world.html');}],['Keep current journey',()=>{}]]);}
function manualSaveCard(){let item=RiftSaves.read(localStorage);return `<div class="manual-save-card"><button id="manual-save-pack" class="primary">Save game</button><button id="load-manual" ${!item?'disabled':''}>Load saved game</button><p class="tiny">${item?'Manual checkpoint: '+esc(item.state.name)+' · Day '+item.state.day+' · '+esc(new Date(item.savedAt).toLocaleString()):'No manual checkpoint yet. Save game creates one without replacing your downloadable backups.'}</p></div>`;}

function notify(t){$('#notice').textContent=t;$('#notice').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('#notice').hidden=true,4200)}
function save(){try{localStorage.setItem(R.KEY,JSON.stringify(state))}catch{notify('Browser storage is unavailable. Export your save before leaving this page.')}}
function go(url){save();location.href=url}
function action(fn){if(!state||!state.started)return;if(state.dead){notify('Your journey has ended. Start again from the title page or import a backup.');return}let msg=fn();save();render();if(msg){notify(msg);if(msg.startsWith('Crafted'))RiftAudio.effect('craft');}}
function header(){if($('#sound-menu'))$('#sound-menu').onclick=showAudio;RiftAudio.setScene(state?.location||'camp');if($('#cheats-menu')){$('#cheats-menu').onclick=showCheats;$('#cheats-badge').hidden=!state?.cheats?.everUsed;$('#cheats-menu').classList.toggle('cheats-used',!!state?.cheats?.everUsed);}document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.nav===(page==='scene'?'world':page)));}
function stats(){return `<div class="metrics">${[['health','Health'],['hunger','Food'],['thirst','Hydration'],['warmth','Warmth']].map(([k,n])=>`<div class="metric"><span>${n}</span><strong class="${state[k]<26?'health':''}">${Math.round(state[k])}<small class="muted tiny"> / 100</small></strong><div class="bar"><i style="width:${state[k]}%;background:${state[k]<26?'#cf8b7d':''}"></i></div></div>`).join('')}</div>`}
function top(title,sub){return `<div class="page-title"><div><div class="eyebrow">${state.quest===6?'Beyond the signal':R.quests[state.quest].chapter}</div><h1>${title}</h1><p>${sub}</p></div><div class="page-meta"><span class="pill">DAY ${state.day} · ${String(state.hour).padStart(2,'0')}:00</span><button id="manual-save" type="button">Save game</button></div></div>${state.dead?'<div class="banner">Your journey has ended. Import a backup from Pack or start a new journey on the title page.</div>':''}${state.quest===6?'<div class="banner">A voice across the ages. Free play unlocked: recruit survivors at camp and fast travel to explored regions.</div>':''}`}
function supplies(){return `<div class="row"><button data-act="eat">Eat · ${state.inv.food||0} rations</button><button data-act="drink">Drink · ${state.inv.water||0} bottles</button></div>`}
function questSummary(){let q=R.quests[state.quest];return `<div class="card"><div class="eyebrow">${q?'Active objective':'Your next chapter'}</div><h3>${q?q.title:'The world is still yours'}</h3><p>${q?q.desc:'Gather, fortify, and explore. The transmitter has opened a route to other survivors.'}</p><a class="tiny gold" href="journal.html">Open quest journal ↗</a></div>`}
function logCard(){return `<div class="card"><div class="eyebrow">Field notes</div><div class="log" aria-live="polite">${state.log.slice(0,7).map(t=>`<p>${esc(t)}</p>`).join('')}</div></div>`}
function render(){header();if(page==='title'){renderTitle();return}if(!state?.started){$('#content').innerHTML='<div class="card"><h1>Your story awaits.</h1><p>Begin your journey to enter the valley.</p><a class="button primary" href="index.html">Begin journey</a></div>';return}if(page==='story'){renderStory();return}let el=$('#content');if(page==='world')el.innerHTML=top('The ancient valley','Every journey costs time. Choose your destination, then venture into the unknown.')+stats()+`<div class="grid"><section><div class="atlas"><div class="atlas-toolbar"><div><span class="eyebrow">Prehistoric Valley</span><span class="atlas-subtitle">Valley of the Echoing Rift</span></div><div class="atlas-tools" role="group" aria-label="Map controls"><button id="map-out" aria-label="Zoom out">−</button><output id="map-zoom" aria-live="polite">100%</output><button id="map-in" aria-label="Zoom in">+</button><button id="map-fit">Fit map</button><button id="map-here" aria-label="Center on your location">Locate me</button><button id="map-labels" aria-pressed="true">Hide labels</button></div></div><div id="map-viewport" class="atlas-viewport" tabindex="0" role="group" aria-label="Interactive valley map. Drag to pan, pinch or use buttons to zoom. Arrow keys pan; plus and minus zoom; zero fits map."><div id="map-stage" class="atlas-stage"><img src="assets/art/valley-map.jpg" width="1376" height="768" alt="Hand-painted prehistoric valley with river camp, glacial peaks, forest trails, eastern meadow, purple rift and monolith." draggable="false"><div id="map-markers"></div></div><div class="atlas-key" aria-hidden="true">◆ YOU &nbsp; ◇ DESTINATION &nbsp; ⌁ LOCKED</div></div><div class="atlas-selection" aria-live="polite"><div><div class="eyebrow" id="selected-kind"></div><h2 id="selected-name"></h2><p id="place-desc"></p><p class="tiny" id="place-meta"></p></div><div class="atlas-actions"><button class="primary" id="travel">Travel to selected site</button><button data-act="gather">Gather / scavenge · 1h</button></div></div></div><details class="atlas-destinations"><summary>All ${R.places.length} destinations · choose a location</summary><div class="locations">${R.places.map(p=>`<button data-place="${p.id}" class="${selected===p.id?'selected':''}">${p.name}${state.location===p.id?' · Here':R.travelLock(state,p.id)?' · Locked':''}</button>`).join('')}</div></details><div class="row"><a class="button primary" href="scene.html">Explore this location ↗</a><button data-act="refill">Refill water · 1h</button><button id="special" class="purple">Investigate site</button><button id="light">Flashlight ${state.flashlight?'on':'off'} · ${state.battery}%</button></div><div class="controls">Select a label to inspect a location, then travel. Drag to pan; pinch, scroll over the map, or use + / − to zoom. Fit map restores the whole valley. On phones, zoom in to show all labels; tap any marker to inspect it. Actions advance the clock; browsing pages does not. Sites replenish each midnight.</div></section><aside>${questSummary()}<div class="card location-art">${locationPanel()}<div class="eyebrow">Your expedition</div><h3>${esc(state.name)} & ${state.companion?'Maya':'the wilderness'}</h3><p>${state.companion?'Herbalist Eye: +2 herbs. Alertness: avoids travel ambushes. +2 expedition carry slots.':'Maya is working at camp. Ask her to accompany you for scouting support.'}</p>${supplies()}${bondInline()}<p class="tiny">Location: ${R.places.find(p=>p.id===state.location).name}</p></div>${logCard()}</aside></div>`;
if(page==='camp')el.innerHTML=top('A place to call home','The world beyond the fire is ancient. What you build here is entirely new.')+stats()+`<div class="grid"><section><div class="camp-scene">${panel(state.flags.walls?'frontier-19':state.flags.fire?'frontier-20':state.flags.shelter?'story-20':'frontier-01')}<div class="scene-caption"><div class="eyebrow">Home · Riverbank</div><h2>${state.flags.shelter?'The first foothold':'A clearing by the river'}</h2></div></div><div class="cards" style="margin-top:16px"><div class="card"><div class="eyebrow">Integrity</div><h2>${state.base}%</h2><p>${state.flags.walls?'Palisade reinforced.':'The perimeter needs protection.'}</p><button data-act="repair">Repair · 3 logs</button></div><div class="card"><div class="eyebrow">The hearth</div><h2>${state.flags.fire?'Burning':'Unlit'}</h2><p>2 logs each midnight. Cold nights drain warmth.</p><a class="button" href="crafting.html">Tend the camp</a></div><div class="card"><div class="eyebrow">Shelter</div><h2>${state.flags.shelter?'Lean-to':'No shelter'}</h2><p>Rest 8 hours to recover 30 health.</p><button data-act="rest">Rest · 8h</button></div></div><div class="card"><div class="eyebrow">Companion · Age 21</div><div class="row spread"><h2>Maya Lin</h2><a class="button" href="scene.html">Explore current location ↗</a></div>${panel(state.maya==='fish'?'frontier-06':state.maya==='forage'?'frontier-18':'story-09','companion-art')}<p class="quote">“${esc(R.Bond.dialogue(state))}”</p><p>${state.companion?'Maya is traveling with you. Camp assignments pause until she returns.':'Maya is at camp. Her assignment produces supplies when a new day begins.'}</p><div class="row"><label for="maya-task">Camp assignment</label><select id="maya-task"><option value="guard">Guard duty · protect camp</option><option value="fish" ${!state.flags.fishing?'disabled':''}>Fishing · ${4+R.Bond.support(state).dailyBonus} raw fish / day</option><option value="forage">Foraging · ${3+R.Bond.support(state).dailyBonus} herbs + ${3+R.Bond.support(state).dailyBonus} berries / day</option><option value="cook">Cooking · 2 fish → ${3+R.Bond.support(state).dailyBonus} rations / day</option></select><button id="companion">${state.companion?'Send Maya to camp':'Bring Maya along'}</button></div><p class="tiny">Fishing is blocked while the Apex Predator quest is active. Cooking needs a burning fire.</p></div>${bondCard()}${state.flags.transmitter?`<div class="card"><div class="eyebrow">Bridging the eras</div><h2>The transmitter</h2><p>Defense waves survived: ${state.waves} / 3. Heal and prepare between waves.</p><div class="row"><button data-act="defend">Defend build site</button><button id="wiring" ${state.waves<3?'disabled':''}>Connect circuit</button>${state.flags.signal?'<button data-act="recruit">Recruit survivor · 3 rations</button>':''}</div><p class="tiny">Survivors recruited: ${state.flags.recruits||0}. Each recruit adds 2 preserved rations on arrival.</p></div>`:''}</section><aside>${questSummary()}<div class="card"><div class="eyebrow">Supplies</div>${supplies()}<p class="tiny">Fire, food, water. Everything else comes after.</p></div>${logCard()}</aside></div>`;
if(page==='scene')el.innerHTML=renderExploration();
if(page==='crafting')el.innerHTML=top('The workbench','Modern ingenuity. Ancient materials. A way forward, one piece at a time.')+`<div class="banner tiny">${state.location==='camp'?`Workbench ready. Crafting takes 1 hour.${state.cheats?.freeCraft?' Free crafting is active: materials are not required.':''}`:'You are away from camp. Return to Riverbank Camp to craft.'} · Modern gear: knife, multi-tool, crowbar, flashlight.</div><div class="cards">${Object.entries(R.recipes).map(([id,r])=>{let built=r.flag&&state.flags[r.flag],locked=(r.requires&&!state.flags[r.requires])||(r.gate&&state.quest<r.gate);return `<article class="card recipe-card">${recipePanel(id)}<div class="eyebrow">${built?'Built & active':locked?'Blueprint locked':r.flag?'Camp & equipment':'Consumable'}</div><h3>${r.title}</h3><p>${r.desc}</p><div class="recipe-cost">${Object.entries(r.cost).map(([k,n])=>`<span style="color:${(state.inv[k]||0)>=n?'#abd9ff':'#e3b391'}">${R.names[k]} ${state.inv[k]||0}/${n}</span>`).join(' · ')}</div>${locked?`<p class="tiny">Requires ${r.requires||R.quests[r.gate-1].title}.</p>`:''}<button data-craft="${id}" ${built||locked||(!state.cheats?.freeCraft&&!R.can(state,r.cost))||state.location!=='camp'?'disabled':''}>${built?'Completed':r.heal?'Make & apply':'Craft · 1h'}</button></article>`}).join('')}</div>`;
if(page==='pack')el.innerHTML=top('What you carry','A few things from the old world. Everything you need to build a new one.')+`<div class="grid"><section><div class="card"><h2>Supplies & materials</h2><p class="tiny">Expedition carry slots: ${(state.fieldLoad||[]).length} / ${state.companion?'10 (+2 with Maya)':'8'}. Each gathered resource type uses one slot; quantities stack. Returning to camp unloads your haul. Modern equipment is carried separately.</p><div class="inventory">${Object.entries(R.names).map(([k,n])=>`<div class="item"><b>${state.inv[k]||0}</b>${n}</div>`).join('')}</div></div><div class="card"><h2>From the old world</h2>${panel('frontier-16')}<p>Heavy canvas work jacket · Pocket knife · Mechanic’s multi-tool · Torn leather gloves · Heavy-duty flashlight · Salvaged crowbar</p><p class="tiny">${state.flags.spear?'Iron spear equipped · ':''}${state.flags.axe?'Iron axe equipped · ':''}${state.flags.coat?'Winter coats equipped':'Canvas jacket equipped'}</p>${supplies()}</div></section><aside><div class="card"><div class="eyebrow">Save your journey</div><h3>Never lose your way.</h3>${manualSaveCard()}<p>Autosaves after each action on this browser and site address. Download a backup to move your progress to another device.</p><button id="export">Export save</button><p><label for="import" class="tiny gold">Import a save (.json)</label><input id="import" type="file" accept=".json,application/json" style="width:100%"></p><p class="tiny">Import replaces current progress after confirmation.</p></div>${questSummary()}</aside></div>`;
if(page==='journal')el.innerHTML=top('Echoes worth keeping','A record of the things that happened. A map of what might happen next.')+`<div class="grid"><section>${bondJournal()}${R.quests.map((q,i)=>`<article class="card quest-card ${i<state.quest?'completed':i===state.quest?'current':''}"><div class="row spread"><div class="eyebrow">${q.chapter}</div><span class="pill">${i<state.quest?'COMPLETE':i===state.quest?'ACTIVE':'UNDISCOVERED'}</span></div><div class="row"><span class="number">0${i+1}</span><h2>${q.title}</h2></div><p>${q.desc}</p>${panel(['frontier-08','frontier-06','frontier-03','frontier-02','frontier-07','frontier-13'][i],'quest-art')}${requirements(i).map(([t,ok])=>`<div class="quest-step ${ok?'done':''}">${ok?'✓':'◇'} ${t}</div>`).join('')}<p class="tiny gold">Reward · ${q.reward}</p></article>`).join('')}<div class="card">${discoveryJournal()}<div class="eyebrow">World notes</div><h2>A world out of sequence</h2><p>The valley resembles the transition out of the last ice age, but the rifts have fractured its ecology. Terror birds displaced from much older eras wander beside dire wolves and giant elk. Their presence is evidence of the anomaly.</p><p>At night the cold returns. Modern fragments fall through short-lived violet tears. The monolith is older than any human structure you know.</p><details><summary>Wildlife field guide · 7 sightings</summary><p>Wildlife beyond the familiar trails. These illustrations document the valley; current combat encounters include wolves, cave bears, and rift-displaced terror birds.</p><div class="field-guide">${panel('frontier-04')}${panel('frontier-09')}${panel('frontier-10')}${panel('frontier-11')}${panel('frontier-12')}${panel('frontier-15')}${panel('frontier-17')}</div></details><details><summary>The collapse · Read the prologue again</summary><p>${storyText().map(x=>x.text).join('</p><p>')}</p></details></div></section><aside><div class="card"><div class="eyebrow">The protagonist · Age 27</div><h2>${esc(state.name)}</h2><p>Engineering student. Gas-station night worker. Owner of a 1986 Ford Foxbody Mustang GT. Mechanic by necessity; survivor by choice.</p></div>${logCard()}</aside></div>`;
bind();if(page==='world'){drawWorld();updateSelection()}bindBond();if(page==='scene')bindExploration();if(state.encounter&&!state.dead)showEncounter();else if(page==='camp'){let ready=R.Bond.next(state);if(ready&&!bondDeferred.has(ready))bondScene(ready);}}
function requirements(i){let v=state.inv,f=state.flags;return [[['Collect 10 fallen logs',(v.log||0)>=10||f.shelter],['Collect 15 fern leaves',(v.leaf||0)>=15||f.shelter],['Build the lean-to using 1 rope',f.shelter]],[['Gather 5 birch saplings',(v.sapling||0)>=5||f.fishing],['Make hooks from 2 copper wire',f.fishing],['Build Maya’s fishing rig',f.fishing]],[['Take Maya to salvage the Ridge wreck',f.salvaged],['Build smelter: 8 stone, 5 clay, 4 metal',f.smelter]],[['Craft an iron spear or 3 traps',f.spear||(v.trap||0)>=3||f.wolf],['Confront the wolf at River Bend',f.wolf]],[['Make winter coats for both travelers',f.coat],['Carry 6 preserved rations and bring Maya',f.monolith||((v.food||0)>=6&&state.companion)],['Follow the trail in Foggy Ravine',f.monolith]],[['Build the transmitter at camp',f.transmitter],['Survive 3 wildlife waves',state.waves===3],['Solve the wiring circuit',f.signal]]][i]}
function bind(){if($('#manual-save'))$('#manual-save').onclick=saveManualGame;if($('#manual-save-pack'))$('#manual-save-pack').onclick=saveManualGame;if($('#load-manual'))$('#load-manual').onclick=loadManualGame;document.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>action(()=>{let a=b.dataset.act;if(a==='eat'||a==='drink'||a==='refill'||a==='battery')return R.use(state,a);if(a==='gather')return R.gather(state);if(a==='rest')return R.rest(state);if(a==='defend')return R.defense(state);if(a==='repair'){if(state.location!=='camp')return 'Return to camp first.';if(!R.can(state,{log:3}))return 'Need 3 logs.';R.pay(state,{log:3});state.base=Math.min(100,state.base+30);R.tick(state,1);return 'Camp repaired.'}if(a==='recruit'){if(state.location!=='camp')return 'Return to camp first.';if(!R.can(state,{food:3}))return 'Need 3 rations.';R.pay(state,{food:3});state.flags.recruits=Math.min(9999,(state.flags.recruits||0)+1);R.add(state,'food',2);R.note(state,'A stranded survivor arrives with two rations. The camp grows.');return 'Survivor recruited.'}}));document.querySelectorAll('[data-craft]').forEach(b=>b.onclick=()=>action(()=>R.craft(state,b.dataset.craft)));document.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>{selected=b.dataset.place;updateSelection();mapView?.focus(selected)});if($('#travel'))$('#travel').onclick=()=>action(()=>R.travel(state,selected));if($('#light'))$('#light').onclick=()=>action(()=>{state.flashlight=!state.flashlight&&state.battery>0;return 'Flashlight '+(state.flashlight?'on.':'off.')});if($('#special'))$('#special').onclick=investigate;if($('#companion'))$('#companion').onclick=()=>action(()=>{if(state.location!=='camp')return 'Return to camp to change Maya’s role.';state.companion=!state.companion;return state.companion?'Maya joins your expedition.':'Maya returns to her camp assignment.'});if($('#maya-task')){$('#maya-task').value=state.maya;$('#maya-task').onchange=e=>action(()=>{if(state.location!=='camp')return 'Return to camp to change assignments.';state.maya=e.target.value;return 'Maya’s assignment updated.'})}if($('#export'))$('#export').onclick=()=>{let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='echoes-of-the-rift-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};if($('#import'))$('#import').onchange=async e=>{try{let file=e.target.files[0];if(!file)return;if(file.size>200000)throw Error('That file is too large.');let imported=JSON.parse(await file.text());if(!R.validate(imported))throw Error('This is not a compatible Echoes of the Rift save.');modal('Restore this journey?',`<p>This will replace current progress with ${esc(imported.name)}’s journey on day ${imported.day}.</p>`,[['Restore save',()=>{state=R.migrate(imported);selected=state.location;save();render()}],['Cancel',()=>{}]])}catch(err){notify(err.message)}};if($('#wiring'))$('#wiring').onclick=wiring;}
function updateSelection(){let p=R.places.find(p=>p.id===selected),lock=R.travelLock(state,p.id),here=selected===state.location;$('#selected-name').textContent=p.name;$('#selected-kind').textContent=p.kind+(here?' · You are here':state.visited[p.id]?' · Explored':' · Unexplored');$('#place-desc').textContent=p.desc;$('#place-meta').textContent=lock||((p.resources.length?'Resources: '+p.resources.map(k=>R.names[k]).join(' · '):'Camp services: rest · craft · refill · Maya')+(here?'':' · Travel '+R.travelHours(state,p.id)+'h'));$('#place-meta').classList.toggle('health',!!lock);document.querySelectorAll('[data-place]').forEach(b=>b.classList.toggle('selected',b.dataset.place===selected));$('#travel').disabled=here||!!lock||state.dead;$('#travel').textContent=here?'You are here':lock?'Destination locked':'Travel to '+p.name+' · '+R.travelHours(state,p.id)+'h';let g=document.querySelector('[data-act="gather"]');g.disabled=state.location==='camp'||state.dead;let quick=state.companion&&state.relationship.synergy&&state.relationship.rhythm===3;g.textContent='Gather at '+R.places.find(p=>p.id===state.location).name+(quick?' · 0h · Synergy':' · 1h');mapView?.select(selected);}

function modal(title,html,actions){let d=$('#dialog');d.oncancel=null;if(d.open)d.close();d.innerHTML=`<h2>${title}</h2>${html}<div class="dialog-actions"></div>`;for(let [label,fn]of actions){let b=document.createElement('button');b.textContent=label;b.onclick=()=>{d.close();fn()};$('.dialog-actions').append(b)}d.showModal()}
function showEncounter(){let e=state.encounter;modal(esc(e.name),`${panel(e.name.includes('bear')?'frontier-04':e.name.includes('bird')?'frontier-12':'frontier-02')}<p class="health">Animal health ${e.hp}/${e.max} · Your health ${state.health}/100</p><p>Maya ${state.companion?'reduces incoming damage by '+R.Bond.support(state).damageReduction+'.':'is not with you.'} ${state.flags.spear?'Iron spear: 24 damage.':'Pocket knife: 12 damage.'}</p><p>Traps: ${state.inv.trap||0} · Rift crystals: ${state.inv.energy||0}</p>`,[['Strike',()=>action(()=>R.fight(state,'attack'))],['Set trap · 20 dmg',()=>action(()=>R.fight(state,'trap'))],['Crystal flare · 30 dmg',()=>action(()=>R.fight(state,'flare'))],['Retreat to camp',()=>action(()=>R.fight(state,'flee'))],['Cheats',()=>showCheats()]]);$('#dialog').oncancel=e=>{e.preventDefault();notify('Choose a combat action or retreat.')}}
function investigate(){if(state.encounter){showEncounter();return}if(state.location==='river'&&state.quest===3){action(()=>R.wolf(state));return}if(state.location==='ravine'&&state.quest===4){if(!state.flags.coat||!state.companion||!R.can(state,{food:6})){notify('Bring Maya, winter coats, and 6 preserved rations.');return}ravine();return}let site=R.places.find(p=>p.id===state.location);if(['glacier','den','meadow','totem','monolith','coast'].includes(site.id)){let text={glacier:'Ice grinds against the mountain. Crystal veins pulse under the frost. Gather here for stone and small amounts of rift energy.',den:'Claw marks cover the rock. Disturbing the den will provoke its resident cave bear.',meadow:'A woolly rhino herd grazes beyond the trail. Maya advises observing from the shelter of the trees. Forage at the edge of the meadow.',totem:'The wolf figures face the same direction as the rift. Spiral carvings match the monolith’s markings. Something has been crossing this valley for a very long time.',monolith:'The monolith hums in answer to your footsteps. You can gather concentrated rift energy here for the transmitter.',coast:'Beyond the delta stretches a sea without ships. Among the stones lies copper from another age. Forage along the shore.'}[site.id];let actions=[['Return to the map',()=>{}]];if(site.id==='den')actions.unshift(['Confront the cave bear',()=>action(()=>{state.encounter={name:'Cave bear',hp:65,max:65,damage:13};return 'The cave bear rises.'})]);modal(site.name,panel(site.art)+'<p>'+text+'</p>',actions);return;}
modal('The valley speaks',`${panel(state.location==='rift'?'frontier-14':state.location==='ridge'?'frontier-16':'frontier-07')}<p>${state.location==='rift'?'Broken signs and car parts appear in the purple light. Gather here for wire, metal, batteries, and rift crystals.':state.location==='ridge'?'Maya can help pry the wreck open. Gather here with her to recover the alternator.':'Old tracks mark the earth. Explore, gather, and follow your current quest.'}</p>`,[['Keep moving',()=>{}]])}
function ravine(){let sequence=[1,5,6,10,14,15],step=0;modal('Signals in the Mist','<p>Follow the cairns from northwest to southeast. Maya’s notes: east, south, east, south, south, east. A wrong turn costs warmth.</p><div class="path-puzzle">'+Array.from({length:16},(_,i)=>`<button data-cell="${i}" aria-label="Trail tile ${i+1}">${i===0?'START':i===15?'◈':'·'}</button>`).join('')+'</div><p id="puzzle-note" class="tiny">Begin one tile east of START.</p>',[['Return to trailhead',()=>{}]]);document.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>{if(state.dead)return;if(+b.dataset.cell===sequence[step]){b.classList.add('chosen');step++;if(step===sequence.length){$('#dialog').close();action(()=>{return R.discover(state,sequence)})}}else{state.warmth=Math.max(0,state.warmth-5);save();$('#puzzle-note').textContent='The fog closes in. Warmth −5. Retrace the marked cairns.'}})}
function wiring(){if(state.flags.signal){notify('The signal is already broadcasting.');return}let sequence=['battery','alternator','crystal','antenna'],step=0;modal('Bridge the eras','<p>Connect the power circuit in engineering order: stored power → regulator → rift core → aerial.</p><div class="row">'+['antenna','battery','crystal','alternator'].map(x=>`<button data-wire="${x}">${{antenna:'Antenna',battery:'Battery',crystal:'Rift crystal',alternator:'Alternator'}[x]}</button>`).join('')+'</div><p id="wire-note" class="tiny">Choose the power source.</p>',[['Step away',()=>{}]]);document.querySelectorAll('[data-wire]').forEach(b=>b.onclick=()=>{if(b.dataset.wire===sequence[step]){b.disabled=true;step++;if(step===4){$('#dialog').close();action(()=>{return R.signal(state,sequence)})}}else{step=0;document.querySelectorAll('[data-wire]').forEach(x=>x.disabled=false);$('#wire-note').textContent='Circuit interrupted. Start again at the power source.'}})}
function storyText(){let n=esc(state?.name||'Leo');return [{title:'The Collapse',tag:'ACT I · THE WORLD YOU KNEW',text:`The afternoon sky turns a bruised purple. ${n}, 27, leaves an engineering lecture in a prized 1986 Ford Foxbody Mustang GT, racing toward another gas-station night shift. Then the highway tears apart. The Mustang slides into the fissure. Daylight vanishes under hundreds of feet of concrete.`,choice:'Pry open the crushed door',note:'The flashlight cuts through smoke. Somewhere beneath the wreckage, a woman calls for help.'},{title:'A voice in the rubble',tag:'ACT I · MAYA LIN',text:`Using the multi-tool and every trick learned under a Mustang’s hood, ${n} shifts the debris. Maya Lin, 21, is trapped beneath a reinforced slab. Her hand reaches through the dust.`,choice:'Free Maya from the rubble',note:'Maya is alive. You find coats, rations, rope, copper wire, and a crowbar in the abandoned cars.'},{title:'The Anomaly',tag:'ACT II · THREE DAYS BELOW',text:'A violet sphere pulses above a perfect circle of clean earth. Around it, cars are sliced in half. The fumes stop at its edge. For three days, you and Maya scavenge the underground graveyard. On the fourth night, the ceiling begins to collapse. Inside the sphere, pine trees sway beneath a blue sky.',choice:'Take Maya’s hand. Enter the rift.',note:'The smoke disappears. Cool air fills your lungs. Behind you, the rift snaps shut.'},{title:'A world before yours',tag:'ACT III · THE ANCIENT VALLEY',text:'Pines tower above an untouched forest. A giant elk moves between the trunks. From somewhere farther away comes a call no living bird should make. Following the sound of water, you find a riverbank. There is no road home. But there is timber, clean water, and the stubborn possibility of tomorrow.',choice:'Establish the riverbank camp',note:'Your survival story begins.'}];}
function renderStory(){let i=Math.min(state.prologue,3),s=storyText()[i];$('#content').innerHTML=`<div class="grid"><section><div class="eyebrow">${s.tag}</div><h1>${s.title}</h1>${storyPanels(i)}<div class="card" style="margin-top:20px"><p style="font:20px/1.85 Georgia;color:#dceaff">${s.text}</p><button id="story-next" class="primary">${s.choice} →</button></div></section><aside><div class="card"><div class="eyebrow">Echoes of the Rift</div><h2>Before the first fire.</h2><p>Engineering student. Night-shift worker. Survivor.</p><p>This is ${esc(state.name)}’s story.</p><p class="tiny">Scene ${i+1} of 4. Story choices advance the prologue.</p><a class="tiny gold" href="world.html">Continue in the valley ↗</a></div></aside></div>`;$('#story-next').onclick=()=>{R.note(state,s.note);state.prologue=Math.min(4,state.prologue+1);save();if(state.prologue>=4)go('world.html');else renderStory()}}
function renderTitle(){if($('#load-manual-title')){$('#load-manual-title').hidden=!RiftSaves.read(localStorage);$('#load-manual-title').onclick=loadManualGame;}if($('#continue')){$('#continue').hidden=!state;$('#continue').textContent=state?'Continue · Day '+state.day:'Continue';$('#continue').onclick=()=>location.href=state.prologue<4?'story.html':'world.html'}$('#new-game').onsubmit=e=>{e.preventDefault();let name=$('#hero-name').value.trim()||'Leo';let start=()=>{state=R.fresh(name);state.started=true;save();go('story.html')};if(state)modal('Begin a new journey?','<p>This replaces the autosave. Export your current journey from Pack first if you want to keep it.</p>',[['Begin new journey',start],['Keep current journey',()=>{}]]);else start()};}
function drawWorld(){let camera=mapView?.camera();mapView?.destroy();mapView=RiftMap.mount({state,selected,camera,onSelect:id=>{selected=id;updateSelection()}});}
$('#dialog').addEventListener('close',()=>{$('#dialog').oncancel=null;if(!$('#dialog').open)RiftAudio.stopVoice();});
render();

})();
